"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
} from "@/lib/takt-surface";

import { useState, useEffect } from "react";
import { useReducedMotion } from "motion/react";

export function StreamingReply({
  className,
  text = "Rhythm, contrast and motion give an interface its shape.",
}: {
  className?: string;
  text?: string;
}) {
  const [revealed, setCount] = useState(0);
  const [running, setRunning] = useState(false);
  const words = text.trim() ? text.trim().split(/\s+/) : [];
  const count = Math.min(revealed, words.length);
  const reduced = useReducedMotion();
  useEffect(() => {
    if (!running || count >= words.length) return;
    const id = setTimeout(() => setCount((i) => i + 1), 85);
    return () => clearTimeout(id);
  }, [running, count, words.length]);
  return (
    <div className={cn(surfacePanel + " grid w-56 gap-2", className)}>
      <p className="min-h-16 rounded-lg bg-muted px-3 py-2.5 text-sm leading-relaxed">
        {count
          ? words.slice(0, count).map((word, i) => (
              <span
                key={i}
                className="inline-block whitespace-pre motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-bottom-1"
              >
                {word}{" "}
              </span>
            ))
          : "Reply preview"}
        {running && count < words.length && (
          <i
            aria-hidden
            className="inline-block size-1.5 rounded-full bg-primary motion-safe:animate-pulse"
          />
        )}
      </p>
      <progress
        aria-label="Reply progress"
        max={Math.max(1, words.length)}
        value={count}
        className="h-1 w-full overflow-hidden rounded-full accent-primary"
      />
      <button
        type="button"
        className={surfaceSecondary}
        disabled={!words.length}
        onClick={() => {
          if (running && count < words.length) {
            setRunning(false);
            return;
          }
          if (count === words.length) setCount(0);
          if (reduced) setCount(words.length);
          setRunning(true);
        }}
      >
        {running && count < words.length
          ? "Pause"
          : count === words.length
            ? "Retry"
            : count
              ? "Resume"
              : "Show reply"}
      </button>
    </div>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
